            for(var route:source.target.ranges()){var child=source.pool.reopenTopologyRange(source.seed.birth(route.groupId()),source.schema);if(child.configuration()==null)child.initializeConfiguration(org.apache.ratis.proto.RaftProtos.RaftConfigurationProto.newBuilder().addPeers(source.peer.getRaftPeerProto()).build().toByteArray());child.applyNoop(new ApplyPosition(1,child.applied()==null?0:child.applied().index()+1),null);child.applyTopologyActivation(new ApplyPosition(1,child.applied().index()+1),source.definition,common,source.catalogue,new ApplyPosition(1,1),commitment);child.enableScopedHistory(RangeMutationHistory.Limits.defaults());child.enableSessionControls();long next=child.applied().index();for(var grant:source.ledger.get().grants())child.apply(new ApplyPosition(1,++next),DistributedCommand.sessionControl(route.groupId(),1,source.schema.digest(),new OperationId(home.controlSession,2,400+grant.epoch()),RangeSessionControl.bind(source.ledger.get(),grant,4096),-1));children.put(route.groupId(),child);}
