            var projection=plan.accept(request.origin().transactionId(),accepted,prepares,finalizes,captures);var initial=base.status().promote(projection.initial());var evidence=new RatisOperationRerouteAdmissionRpc.Evidence(request.original(),source.directory,source.target,home.sourceOutcome(request.original()),projection.intents());homes.prepareEvidence(home,home.command(RatisSourceOutcomeRpc.control(request,128),base.status(),initial),evidence);home.apply(home.command(RatisSourceOutcomeRpc.control(request,128),base.status(),initial));var status=initial;int control=129;
            for(var intent:projection.intents()){var child=children.get(intent.route().groupId());var preparation=new PreparedParticipant.Preparation(home.groupId,1,intent.prepareControl(),initial,intent.acceptedBusiness());var vote=child.applyPrepared(new ApplyPosition(1,child.applied().index()+1),preparation);assertTrue(vote.prepared());var next=status.prepared(intent.route().groupId(),intent.acceptedBusiness().payloadDigest(),vote.position());home.apply(home.command(RatisSourceOutcomeRpc.control(request,control++),status,next));status=next;}
            var decision=status.decide(TransactionStatus.Phase.COMMIT);home.apply(home.command(RatisSourceOutcomeRpc.control(request,control++),status,decision));status=decision;
