    @Test void creditThenActualChildCommitPublishesOriginalGlobalResultAndRetriesWithoutProofReads()throws Exception {
        try(var f=new Fixture(root.resolve("commit"),true)){
            var creditProposal=new RatisSourceOutcomeRpc.Proposal(RatisSourceOutcomeRecord.Kind.CREDIT,f.request,List.of());var creditRecord=new RatisSourceOutcomeRecord(RatisSourceOutcomeRecord.Kind.CREDIT,f.request,null);assertNotNull(f.propose(creditRecord).getException());assertThrows(ExecutionException.class,()->f.machine.query(message(RatisSourceOutcomeRpc.prepare(creditProposal))).get(5,TimeUnit.SECONDS));
            byte[] request=RatisSourceOutcomeRpc.prepare(creditProposal);assertArrayEquals(request,RatisSourceOutcomeRpc.prepare(RatisSourceOutcomeRpc.proposal(request)));assertThrows(IllegalArgumentException.class,()->RatisSourceOutcomeRpc.proposal(Arrays.copyOf(request,request.length-1)));assertFalse(f.prepare(creditProposal).fenced());var credit=f.apply(creditRecord);assertEquals(NativeSourceOutcomePublication.Outcome.RETAINED,credit.outcome());assertNotNull(f.home.source.store.sourceOutcomeCredit(f.request.original().operationId(),f.request.original().receiptDigest()));
            var accepted=f.commitChildren();var publicationProposal=new RatisSourceOutcomeRpc.Proposal(RatisSourceOutcomeRecord.Kind.PUBLISH,f.request,accepted.intents());f.unavailableOutcomes=true;assertThrows(ExecutionException.class,()->f.prepare(publicationProposal));assertNull(f.home.source.store.operationResult(f.request.original().operationId(),f.request.original().receiptDigest()));f.unavailableOutcomes=false;
            var record=f.prepare(publicationProposal).record();assertArrayEquals(record.encode(),RatisSourceOutcomeRecord.decode(record.encode()).encode());var result=CommandResult.decode(record.result());assertEquals(4,result.valueCount());for(int n=0;n<4;n++)assertArrayEquals(new byte[]{(byte)new int[]{20,10,21,11}[n]},result.value(n));
            var published=f.apply(record);assertEquals(NativeSourceOutcomePublication.Outcome.RETAINED,published.outcome());var original=NativeSourceOutcomePublication.decode(published.proof());assertArrayEquals(record.result(),f.home.source.store.operationResult(f.request.original().operationId(),f.request.original().receiptDigest()));assertTrue(f.home.source.store.sourceOutcomeCredits().isEmpty());assertEquals(0,f.home.source.store.activeSnapshotPins());
            f.beforeHome=()->{throw new AssertionError("Saved source publication must not read HOME/participants again");};assertEquals(record,f.prepare(new RatisSourceOutcomeRpc.Proposal(record.kind(),f.request,List.of(),record)).record());var retry=f.apply(record);assertEquals(original,NativeSourceOutcomePublication.decode(retry.proof()));assertArrayEquals(record.result(),f.home.source.store.operationResult(f.request.original().operationId(),f.request.original().receiptDigest()));
        }
    }
    @Test void acknowledgementQualifiesActualSealedSchemaWithoutRebasingOriginalBusiness()throws Exception {
        try(var f=new RatisTopologyCdcPollTest.Fixture(root.resolve("ack-schema"))){
            var original=new DistributedCommand(f.groupId,1,f.schema.digest(),new OperationId(f.session,1,1),List.of(new Mutation(Mutation.Kind.PUT,f.column,new byte[]{10},new byte[]{7})));byte[] originalBytes=DistributedCommandCodec.encode(original);byte[] result=f.apply(original);
            UUID extra=id(801);var columns=new ArrayList<>(f.schema.columns());columns.add(new DistributedSchema.Column(2,extra,"extra",f.schema.columns().getFirst().schema(),null));var newer=new DistributedSchema(f.cluster,f.database,f.domain,2,0,columns);var schemaChange=new SchemaChange.Definition(id(802),new OperationId(id(803),1,0),f.directory,f.schema,newer);
            f.store.applySchemaFence(new ApplyPosition(1,++f.index),schemaChange.header());NativeSchemaInstallProof installation;try(var gate=f.store.prepareSchemaInstallation(schemaChange.header());var plan=f.pool.prepareSchemaInstallation(f.store,schemaChange)){assertTrue(gate.ready());installation=f.pool.installSchema(f.store,new ApplyPosition(1,++f.index),plan).proof();}f.store.applySchemaActivation(new ApplyPosition(1,++f.index),installation,f.catalogue,new ApplyPosition(1,1));
            var source=schemaChange.targetDirectory();var target=new RangeDirectory(f.cluster,f.database,f.domain,2,newer.digest(),source.generation()+1,newer.columnIds(),source.routingPrefixBytes(),f.target.ranges());var topology=new TopologyChange.Definition(id(804),source,target);byte[] initial=TopologyChange.State.begin(topology.header()).beginFencing().encode();byte[] admission=OperatorUpload.sha256(ByteBuffer.allocate(16+initial.length).putLong(f.catalogue.getMostSignificantBits()).putLong(f.catalogue.getLeastSignificantBits()).put(initial).array());f.freeze=f.store.applyTopologyFreeze(new ApplyPosition(1,++f.index),topology,admission);f.machine.notifyTermIndexUpdated(1,f.index);
            var transport=new RatisRoutedClient.Transport(){public byte[] read(RangeDescriptor route,UUID column,byte[] key)throws IOException{throw new IOException("No USER reads in source ACK fixture");}public CommandResult command(RangeDescriptor route,DistributedCommand command)throws IOException{assertEquals(f.groupId,route.groupId());try{byte[] bytes=f.store.apply(new ApplyPosition(1,f.store.applied().index()+1),command);f.index=f.store.applied().index();f.machine.notifyTermIndexUpdated(1,f.index);return CommandResult.decode(bytes);}catch(org.rocksdb.RocksDBException|RuntimeException failure){throw new IOException(failure);}}public byte[] transaction(RangeDescriptor route,byte[] request,boolean fresh)throws IOException{assertTrue(fresh);assertEquals(f.groupId,route.groupId());try{return f.machine.queryLinearizable(message(request)).get(5,TimeUnit.SECONDS).getContent().toByteArray();}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IOException(interrupted);}catch(ExecutionException|TimeoutException failure){throw new IOException(failure);}}};
            try(var routed=new RatisRoutedClient(f.directory,transport)){
                var oldAck=routed.prepareAcknowledgementAt(new OperationId(f.session,1,2),f.directory,f.parent,1);assertThrows(IOException.class,()->routed.execute(oldAck));assertArrayEquals(result,f.store.operationResult(original.operationId(),original.receiptDigest()));
                var preparedOriginal=routed.restoreSessionCommand(f.directory,original,f.parent);var qualified=routed.qualifyAcknowledgementSource(preparedOriginal,header->{assertArrayEquals(topology.header().encode(),header.encode());return topology.sourceDirectory();});assertEquals(newer.columnIds(),qualified.directory().columns());assertEquals(2,qualified.directory().schemaEpoch());assertEquals(RatisTopologyOperationOutcomeRpc.Outcome.FOUND,qualified.evidence().outcome());
                var ack=routed.prepareAcknowledgementAt(new OperationId(f.session,1,2),qualified.directory(),qualified.parent(),1);assertArrayEquals(newer.digest(),ack.command().schemaDigest());assertEquals(original.groupId(),ack.command().groupId());assertEquals(original.rangeEpoch(),ack.command().rangeEpoch());assertTrue(ack.command().mutations().isEmpty());assertTrue(ack.command().predicates().isEmpty());assertArrayEquals(originalBytes,DistributedCommandCodec.encode(preparedOriginal.command()));assertArrayEquals(f.schema.digest(),preparedOriginal.command().schemaDigest());
                assertEquals(CommandResult.Status.SUCCESS,routed.execute(ack).status());assertEquals(CommandResult.Status.SESSION_EXPIRED,CommandResult.decode(f.store.operationResult(original.operationId(),original.receiptDigest())).status());assertEquals(CommandResult.Status.SUCCESS,routed.execute(ack).status());assertEquals(0,f.store.activeSnapshotPins());
            }
        }
    }
    @Test void preparedCreditOwnsOriginalIdentityBeforeNativeReceiptCreditExists()throws Exception {
        try(var f=new Fixture(root.resolve("identity"),false)){
            var proposal=new RatisSourceOutcomeRpc.Proposal(RatisSourceOutcomeRecord.Kind.CREDIT,f.request,List.of());var record=f.prepare(proposal).record();assertNull(f.home.source.store.sourceOutcomeCredit(f.request.original().operationId(),f.request.original().receiptDigest()));
            var original=f.request.original();var poisoningAck=new DistributedCommand(original.groupId(),original.rangeEpoch(),original.schemaDigest(),original.operationId(),List.of(),List.of(),0);assertFalse(Arrays.equals(original.receiptDigest(),poisoningAck.receiptDigest()));
            var tx=f.machine.startTransaction(RaftClientRequest.newBuilder().setClientId(ClientId.randomId()).setServerId(f.home.source.peer.getId()).setGroupId(f.home.source.group.getGroupId()).setCallId(1).setType(RaftClientRequest.writeRequestType()).setMessage(message(DistributedCommandCodec.encode(poisoningAck))).build());assertNotNull(tx.getException());assertEquals(1,f.machine.sourceOutcomeStats().holds());assertNull(f.home.source.store.operationResult(original.operationId(),original.receiptDigest()));assertEquals(NativeSourceOutcomePublication.Outcome.RETAINED,f.apply(record).outcome());assertNotNull(f.home.source.store.sourceOutcomeCredit(original.operationId(),original.receiptDigest()));assertEquals(0,f.machine.sourceOutcomeStats().holds());
        }
    }
    @Test void committedClockAdvanceDoesNotInvalidateBoundedSealedSourceProof()throws Exception {
        try(var f=new Fixture(root.resolve("clock"),false)){
            var entered=new CountDownLatch(1);var release=new CountDownLatch(1);f.beforeHome=()->{entered.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("Fixture timeout");}catch(InterruptedException interrupted){throw new AssertionError(interrupted);}};
            var proposal=new RatisSourceOutcomeRpc.Proposal(RatisSourceOutcomeRecord.Kind.CREDIT,f.request,List.of());try{var future=f.machine.queryLinearizable(message(RatisSourceOutcomeRpc.prepare(proposal)));assertTrue(entered.await(5,TimeUnit.SECONDS));var before=f.home.source.store.applied();assertEquals(CommandResult.Status.SUCCESS,CommandResult.decode(f.applyControl(f.home.source.clock(20,20))).status());assertTrue(f.home.source.store.applied().index()>before.index());assertEquals(1,f.machine.sourceOutcomeStats().count());release.countDown();var prepared=RatisSourceOutcomeRpc.prepared(future.get(5,TimeUnit.SECONDS).getContent().toByteArray(),proposal);assertFalse(prepared.fenced());assertEquals(NativeSourceOutcomePublication.Outcome.RETAINED,f.apply(prepared.record()).outcome());assertEquals(0,f.machine.sourceOutcomeStats().holds());assertEquals(0,f.home.source.store.activeSnapshotPins());}finally{release.countDown();}
        }
    }
    @Test void canonicalExpiredEmptyHomePublishesExpiredReceiptWithCapturedImagesAndLaggingSourceClock()throws Exception {
        try(var f=new Fixture(root.resolve("canonical-expiry"),false)){
            var credit=f.prepare(new RatisSourceOutcomeRpc.Proposal(RatisSourceOutcomeRecord.Kind.CREDIT,f.request,List.of())).record();f.apply(credit);var captured=f.homes.controlledAccepted(f.home,f.base);
            f.home.source.ledger.set(f.home.source.ledger.get().advanceTime(SessionEpochLedger.MAX_LIFETIME_MILLIS+11));var authority=f.home.source.ledger.get();f.home.apply(DistributedCommand.sessionControl(f.home.groupId,1,new byte[32],new OperationId(f.home.controlSession,authority.minimumEpoch(),500),RangeSessionControl.advance(authority),-1));f.abortHome(TransactionStatus.NoEffectOutcome.SESSION_EXPIRED);
            assertFalse(f.home.source.store.estimateSourceOutcomeCredit(f.request).fenced());var record=f.prepare(new RatisSourceOutcomeRpc.Proposal(RatisSourceOutcomeRecord.Kind.PUBLISH,f.request,captured.intents())).record();assertEquals(CommandResult.Status.SESSION_EXPIRED,CommandResult.decode(record.result()).status());assertEquals(NativeSourceOutcomePublication.Outcome.RETAINED,f.apply(record).outcome());assertEquals(CommandResult.Status.SESSION_EXPIRED,CommandResult.decode(f.home.source.store.operationResult(f.request.original().operationId(),f.request.original().receiptDigest())).status());assertTrue(f.children.isEmpty());assertTrue(f.home.source.child.topologyBirthPending());assertEquals(0,f.home.source.store.activeSnapshotPins());
        }
    }
    @Test void cancelledCreditProofRetainsActualOwnerAndNoNativeCreditUntilCallbackReturns()throws Exception {
        try(var f=new Fixture(root.resolve("cancel"),false)){
            var entered=new CountDownLatch(1);var release=new CountDownLatch(1);f.beforeHome=()->{entered.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("Fixture timeout");}catch(InterruptedException interrupted){throw new AssertionError(interrupted);}};
            var proposal=new RatisSourceOutcomeRpc.Proposal(RatisSourceOutcomeRecord.Kind.CREDIT,f.request,List.of());try{var future=f.machine.queryLinearizable(message(RatisSourceOutcomeRpc.prepare(proposal)));assertTrue(entered.await(5,TimeUnit.SECONDS));assertTrue(future.cancel(false));assertEquals(1,f.machine.sourceOutcomeStats().reading());assertEquals(1,f.machine.sourceOutcomeStats().count());assertEquals(2*RatisProofQueryService.IMPORT_PUBLICATION_BYTES,f.queries.stats().bytes());
                byte[] cancel=f.machine.queryLinearizable(message(RatisSourceOutcomeRpc.cancel(proposal.kind(),f.request))).get(5,TimeUnit.SECONDS).getContent().toByteArray();RatisSourceOutcomeRpc.requireCancelled(cancel,proposal.kind(),f.request);assertEquals(1,f.machine.sourceOutcomeStats().count());assertNull(f.home.source.store.sourceOutcomeCredit(f.request.original().operationId(),f.request.original().receiptDigest()));release.countDown();f.queries.stop().get(5,TimeUnit.SECONDS);assertEquals(0,f.machine.sourceOutcomeStats().holds());assertEquals(0,f.queries.stats().bytes());
            }finally{release.countDown();}
        }
    }
